(()=>{'use strict';const $=k=>document.getElementById('M06-'+k),zh=document.documentElement.lang.startsWith('zh'),X=[[-2,-1],[-1,-.8],[0,.4],[1,.6],[2,.8]];let s;const text=(x,y,t,c='#29404e',size=17)=>`<text x="${x}" y="${y}" fill="${c}" font-family="sans-serif" font-size="${size}">${t}</text>`,px=x=>315+100*x,py=y=>255-100*y;
function draw(){const angle=+$('angle').value,selected=+$('point').value,a=angle*Math.PI/180,u=[Math.cos(a),Math.sin(a)],dots=X.map(x=>x[0]*u[0]+x[1]*u[1]),P=dots.map(d=>[d*u[0],d*u[1]]),errors=X.map((x,i)=>(x[0]-P[i][0])**2+(x[1]-P[i][1])**2),ret=dots.reduce((a,d)=>a+d*d,0)/5,err=errors.reduce((a,b)=>a+b,0)/5;s={angle,selected,retained_variance:ret,reconstruction_error:err,total_variance:2.56,selected_error:errors[selected],projection:P[selected]};$('angle-value').textContent=angle.toFixed(1);$('point-value').textContent=selected+1;let v=text(30,35,zh?'五点的正交投影':'Orthogonal projection of five observations');[-2,-1,0,1,2].forEach(t=>{v+=`<line x1="${px(t)}" y1="95" x2="${px(t)}" y2="415" stroke="#e1e7eb"/>`+text(px(t)-5,440,t,'#647585',14)});[-1,0,1].forEach(t=>{v+=`<line x1="65" y1="${py(t)}" x2="565" y2="${py(t)}" stroke="#e1e7eb"/>`+text(40,py(t)+5,t,'#647585',14)});v+=`<line x1="${px(-2.45*u[0])}" y1="${py(-2.45*u[1])}" x2="${px(2.45*u[0])}" y2="${py(2.45*u[1])}" stroke="#d87430" stroke-width="2"/>`;X.forEach((x,i)=>{v+=`<line x1="${px(x[0])}" y1="${py(x[1])}" x2="${px(P[i][0])}" y2="${py(P[i][1])}" stroke="${i===selected?'#943e52':'#aab6bf'}" stroke-width="${i===selected?3:1.5}" stroke-dasharray="4 3"/><circle cx="${px(P[i][0])}" cy="${py(P[i][1])}" r="5" fill="#d87430"/><circle data-point="${i}" cx="${px(x[0])}" cy="${py(x[1])}" r="${i===selected?10:7}" fill="#237b94" stroke="#ffffff" stroke-width="2"/>`+text(px(x[0])+12,py(x[1])-8,i+1,'#237b94',15)});v+=text(240,475,zh?'特征1（无量纲）':'Feature 1 (unitless)')+text(35,70,zh?'特征2':'Feature 2');v+=text(620,100,zh?'平均平方长度 = 2.56':'Mean squared length = 2.56',undefined,16);v+=`<rect x="640" y="${405-ret*90}" width="65" height="${ret*90}" fill="#237b94"/><rect x="750" y="${405-err*90}" width="65" height="${err*90}" fill="#d87430"/>`+text(635,435,zh?'保留':'Retained',undefined,16)+text(745,435,zh?'残差':'Residual',undefined,16)+text(635,395-ret*90,ret.toFixed(3),'#237b94',16)+text(745,395-err*90,err.toFixed(3),'#d87430',16)+text(620,480,zh?'柱高：均方长度':'Bar height: mean squared length',undefined,15);$('plot').innerHTML=v;$('result').textContent=(zh?'记录 ':'Record ')+(selected+1)+(zh?' 的重建平方误差 ':' squared reconstruction error ')+s.selected_error.toFixed(4)+(zh?'；平均重建平方误差 ':'; mean squared reconstruction error ')+err.toFixed(4)+(zh?'；保留与残差相加 ':'; retained plus residual ')+(ret+err).toFixed(4);}
function set(p={}){if(p.angle!==undefined)$('angle').value=Math.max(-90,Math.min(90,+p.angle));if(p.selected!==undefined)$('point').value=Math.max(0,Math.min(4,Math.round(p.selected)));draw();return s}function reset(){return set({angle:0,selected:4})}['angle','point'].forEach(x=>$(x).addEventListener('input',draw));$('optimal').addEventListener('click',()=>set({angle:Math.atan2(2,1.44)*90/Math.PI}));$('reset').addEventListener('click',reset);$('plot').addEventListener('click',e=>{if(e.target.dataset.point!==undefined)set({selected:+e.target.dataset.point})});window.CourseLab={set,state:()=>structuredClone(s),reset};reset()})();
